        width: min(920px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4rem 0 3rem;
      }

      .hero {
        margin-bottom: 1.5rem;
        padding: 1.75rem;
        border: 1px solid var(--border);
        border-radius: 24px;
        background: linear-gradient(180deg, rgba(24, 33, 60, 0.98), rgba(17, 24, 45, 0.98));
        box-shadow: 0 24px 64px rgba(5, 8, 22, 0.45);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        margin: 0;
        color: var(--muted);
        max-width: 65ch;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        border: 1px solid var(--border);
        border-radius: 20px;
        background: rgba(17, 24, 45, 0.92);
        box-shadow: 0 16px 36px rgba(5, 8, 22, 0.28);
        padding: 1rem;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        font-size: 1.08rem;
        font-weight: 700;
      }

      .question-meta {
        margin-top: 0.35rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .options {
        margin: 1rem 0 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 0.75rem;
      }

      .option-label {
        display: grid;
        grid-template-columns: 1.125rem 1fr;
        gap: 0.875rem;
        align-items: start;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: linear-gradient(180deg, var(--panel-2), var(--panel));
        cursor: pointer;
        transition: border-color 0.15s ease, transform 0.15s ease, background 0.15s ease;
      }

      .option-label:hover {
        border-color: var(--accent);
        transform: translateY(-1px);
      }

      .option-label:focus-within {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      input[type="checkbox"] {
        appearance: none;
        width: 1.125rem;
        height: 1.125rem;
        margin: 0.1rem 0 0;
        border-radius: 0.35rem;
        border: 2px solid #6c7aa9;
        background: #0b1020;
        display: grid;
        place-content: center;
        flex: none;
      }

      input[type="checkbox"]::before {
        content: "";
        width: 0.55rem;
        height: 0.55rem;
        transform: scale(0);
        transition: transform 0.12s ease-in-out;
        clip-path: polygon(14% 44%, 0 59%, 38% 100%, 100% 18%, 84% 0, 38% 62%);
        background: var(--accent);
      }

      input[type="checkbox"]:checked {
        border-color: var(--accent);
        background: rgba(124, 156, 255, 0.16);
      }

      input[type="checkbox"]:checked::before {
        transform: scale(1);
      }

      input[type="checkbox"]:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .option-copy {
        display: grid;
        gap: 0.15rem;
      }

      .option-title {
        font-weight: 600;
      }

      .option-note {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .actions {
        display: flex;
        gap: 0.75rem;
        align-items: center;
        flex-wrap: wrap;
        margin-top: 0.25rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.35rem;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        color: #081120;
        font-weight: 800;
        font-size: 1rem;
        cursor: pointer;
        box-shadow: 0 12px 28px rgba(124, 156, 255, 0.3);
      }

      button:hover {
        filter: brightness(1.05);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .feedback {
        min-height: 1.5rem;
        color: var(--muted);
      }

      .feedback strong {
        color: var(--success);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 640px) {
        main {
          width: min(100% - 1rem, 920px);
          padding-top: 3.25rem;
        }

        .hero,
        .form-field {
          border-radius: 18px;
        }
      }

      @media (forced-colors: active) {
        .skip-link,
        .hero,
        .form-field,
        .option-label,
        button {
          forced-color-adjust: auto;
          border: 1px solid ButtonBorder;
          background: Canvas;
          color: CanvasText;
          box-shadow: none;
        }

        .skip-link:focus,
        .option-label:focus-within,
        button:focus-visible,
        input[type="checkbox"]:focus-visible {
          outline: 2px solid Highlight;
          outline-offset: 2px;
        }

        input[type="checkbox"] {
          border-color: ButtonText;
          background: Canvas;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="root"></div>

    <script>
      const quizData = [
        {
          id: "languages",
          title: "Which of these are programming languages?",
          helpText: "Select all answers that you think belong in the programming languages category.",
          options: [
            { id: "javascript", label: "JavaScript", note: "Used across web and server-side development." },
            { id: "python", label: "Python", note: "Popular for automation, web, and data work." },
            { id: "html", label: "HTML", note: "A markup language, not a programming language." },
            { id: "rust", label: "Rust", note: "A systems programming language focused on safety." },
          ],
        },
        {
          id: "compiled",
          title: "Which languages are commonly compiled before running?",
          options: [
            { id: "c", label: "C", note: "Typically compiled to machine code." },
            { id: "go", label: "Go", note: "Commonly compiled into native binaries." },
            { id: "css", label: "CSS", note: "A style sheet language, not compiled as code." },
            { id: "swift", label: "Swift", note: "Often compiled for Apple platforms." },
          ],
        },
        {
          id: "paradigms",
          title: "Which languages are known for functional programming features?",
          options: [
            { id: "haskell", label: "Haskell", note: "Strongly associated with functional programming." },
            { id: "elixir", label: "Elixir", note: "Runs on the Erlang VM and supports functional style." },
            { id: "php", label: "PHP", note: "Primarily used for web scripting." },
            { id: "fsharp", label: "F#", note: "A functional-first language on .NET." },
          ],
        },
      ];

      const answerKey = {
        languages: ["javascript", "python", "rust"],
        compiled: ["c", "go", "swift"],
        paradigms: ["haskell", "elixir", "fsharp"],
      };

      function QuestionCard(question) {
        const helpId = question.helpText ? `${question.id}-help` : "";
        const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";
        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${question.title}</legend>
              ${question.helpText ? `<p class="question-meta" id="${helpId}">${question.helpText}</p>` : ""}
              <ul class="options">
                ${question.options
                  .map(
                    (option) => `
                      <li>
                        <label class="option-label" for="${question.id}-${option.id}">
                          <input
                            type="checkbox"
                            id="${question.id}-${option.id}"
                            name="${question.id}"
                            value="${option.id}"
                          />
                          <span class="option-copy">
                            <span class="option-title">${option.label}</span>
                            <span class="option-note">${option.note}</span>
                          </span>
                        </label>
                      </li>
                    `
                  )
                  .join("")}
              </ul>
            </fieldset>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <main id="main">
            <section class="hero" aria-labelledby="quiz-title">
              <h1 id="quiz-title">Computer Languages Quiz</h1>
              <p class="lead">Choose every answer that applies for each question, then submit your selections to see how you did.</p>
            </section>

            <form id="quiz-form" novalidate>
              ${quizData.map(QuestionCard).join("")}
              <div class="actions">
                <button type="submit">Submit quiz</button>
                <p class="feedback" id="feedback" aria-live="polite"></p>
              </div>
            </form>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = QuizApp();

      const form = document.getElementById("quiz-form");
      const feedback = document.getElementById("feedback");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let score = 0;
        const total = quizData.length;

        quizData.forEach((question) => {
          const selected = [...form.querySelectorAll(`input[name="${question.id}"]:checked`)].map((input) => input.value).sort();
          const expected = [...answerKey[question.id]].sort();
          if (selected.length === expected.length && selected.every((value, index) => value === expected[index])) {
            score += 1;
          }
        });

        feedback.innerHTML = `<strong>${score} of ${total}</strong> questions answered correctly.`;
      });
    </script>
  </body>
</html>
